export const BODY: string = "\n<p>تصویر میں چہرہ یا پتہ چھپانے میں صرف چند منٹ لگتے ہیں۔ آپ برش سے حساس حصے پر رنگ کرتے ہیں، نتیجہ جانچتے ہیں اور سنسر شدہ کاپی ڈاؤن لوڈ کر لیتے ہیں۔</p>\n<p>یہ رہنما پورا طریقہ بتاتا ہے۔ اس میں برش اور پوری تصویر والے موڈ، بلر اور پکسلیشن، برش کا سائز اور وہ جانچیں شامل ہیں جن سے یقین ہو جاتا ہے کہ کچھ بھی پڑھا نہیں جا سکتا۔</p>\n<p>آخر تک آپ چہرہ، نمبر پلیٹ، اسکرین شاٹ یا دستاویز کی تصویر ہر ڈیوائس پر صاف طریقے سے سنسر کر سکیں گے۔ ڈاؤن لوڈ جانچنے تک اصل تصویر الگ رکھیں۔</p>\n<h2 id=\"before-you-start\">شروع کرنے سے پہلے: چھپانے والی چیزیں لکھیں</h2>\n<p>اصل تصویر کھول کر ہر حساس چیز کی فہرست بنائیں: چہرے، پتے، نمبر پلیٹیں، اسکرینیں، دستاویزات اور بیج پر لکھے نام۔ پس منظر بھی دیکھیں، صرف سامنے والا حصہ نہیں۔</p>\n<p>عکاسیوں پر بھی نظر رکھیں۔ چہرہ آئینے، کھڑکی یا دھوپ کے چشمے میں بھی نظر آ سکتا ہے، اور اس کی ہر کاپی سنسر کرنی ہوتی ہے، صرف اصل چہرہ نہیں۔</p>\n<p>شروع کرنے سے پہلے طے کریں کہ بلر کرنا ہے یا پکسلیٹ۔ متن اور نمبروں کے لیے پکسلیشن زیادہ محفوظ ہے، جبکہ چہرے اور پس منظر کے لیے سخت بلر اچھا کام کرتا ہے۔ <a href=\"/ur/tasveer-blur-pixelate-karein/\">Blur and Pixelate Image ٹول</a> براؤزر میں کھولیں۔</p>\n<h2 id=\"step-by-step\">چھ مرحلوں میں تصویر بلر یا پکسلیٹ کریں</h2>\n<p>چہرے، نمبر پلیٹ یا اسکرین شاٹ کے لیے طریقہ ایک جیسا ہے۔ اپ لوڈ کریں، موڈ چنیں، رنگیں یا لگائیں، جانچیں اور ڈاؤن لوڈ کریں۔</p>\n<p>رنگنے والے مرحلے پر وقت لگائیں۔ اب احتیاط سے کیا گیا برش اسٹرک آپ کو اس شرمندگی سے بچاتا ہے کہ تصویر شیئر کرنے کے بعد کوئی تفصیل پڑھی جا سکے۔</p>\n<ol>\n<li>تصویر کو ڈراپ زون میں گھسیٹ کر، اپنے آلے سے چن کر یا Ctrl+V سے اسکرین شاٹ پیسٹ کر کے اپ لوڈ کریں۔</li>\n<li>خاص تفصیل رنگنے کے لیے Brush Area موڈ چنیں، یا پوری تصویر بلر کرنے کے لیے Whole Image موڈ چنیں۔</li>\n<li>Smooth Blur یا Pixelate Mosaic چنیں، پھر برش کا سائز اور شدت یا بلاک سائز طے کریں۔</li>\n<li>برش سے ہر حساس حصے پر رنگیں، چہرے مکمل اور متن کھلے دل سے ڈھانپیں۔</li>\n<li>زوم کر کے نتیجہ کا پیش نظارہ دیکھیں اور یقین کریں کہ کچھ بھی پڑھا یا پہچانا نہیں جا سکتا۔</li>\n<li>ایکسپورٹ فارمیٹ اور کوالٹی چنیں، پھر Download پر کلک کر کے سنسر شدہ تصویر محفوظ کریں۔</li>\n</ol>\n<p>شیئر کرنے سے پہلے ڈاؤن لوڈ شدہ فائل ایک بار کھول کر دیکھیں۔ مکمل سائز میں جانچیں اور یقین کریں کہ ہر حساس تفصیل چھپی ہوئی ہے۔</p>\n<h2 id=\"choosing-blur-or-pixelate\">بلر اور پکسلیشن میں سے کیا چنیں</h2>\n<p>چہرے اور پس منظر کے لیے Smooth Blur چنیں۔ سخت بلر خدوخال مٹا دیتا ہے مگر تصویر قدرتی لگتی ہے، اور یہ پورٹریٹ کے لیے موزوں ہے۔</p>\n<p>متن، نمبروں اور پتوں کے لیے Pixelate Mosaic چنیں۔ موزیک بلاک حروف کی شکلیں مکمل طور پر توڑ دیتے ہیں، جبکہ نرم بلر ان کی خاکہ پڑھنے کے قابل چھوڑ سکتا ہے۔</p>\n<p>ایک ہی تصویر پر دونوں ملا سکتے ہیں۔ چہرے پر بلر رنگیں اور نمبر پلیٹ پر پکسلیشن، اسٹرک کے درمیان موڈ بدل کر۔ شک ہو تو پکسلیشن استعمال کریں، کیونکہ تھوڑا سخت موزیک جان بوجھ کر کیا لگتا ہے۔</p>\n<h2 id=\"using-brush-mode\">برش ایریا موڈ استعمال کرنا</h2>\n<p>برش ایریا موڈ درست انتخاب ہے۔ آپ اثر بالکل وہیں رنگتے ہیں جہاں ضرورت ہے، اور باقی تصویر تیز اور اچھوتی رہتی ہے۔</p>\n<p>بڑے حصے، جیسے پورا چہرہ، کے لیے بڑے برش سے شروع کریں۔ سر مکمل ڈھانپیں، صرف آنکھیں نہیں، بالوں کی لکیر، کان اور ٹھوڑی بھی۔</p>\n<p>کناروں کے لیے چھوٹے برش پر جائیں۔ چھوٹا برش ایک لفظ کے گرد گھومنے یا سنسر شدہ حصے کی سرحد صاف کرنے دیتا ہے۔ انڈو بٹن آخری اسٹرک ہٹاتا ہے اور ری سیٹ تمام اسٹرک صاف کر دیتا ہے۔</p>\n<h2 id=\"using-whole-image-mode\">پوری تصویر والا موڈ استعمال کرنا</h2>\n<p>Whole Image موڈ ایک ہی بار میں پوری تصویر پر اثر لگا دیتا ہے۔ یہ اس وقت درست ہے جب پوری تصویر حساس ہو، یا جب آپ ڈیزائن کے لیے دھندلا پس منظر چاہتے ہوں۔</p>\n<p>ٹارگٹ ایریا کو Whole Image پر بدلیں تو آپ کی موجودہ بلر یا پکسلیشن شدت پورے فریم پر لگ جاتی ہے۔ رنگ اور موڈ رہتے ہیں، مگر کوئی تفصیل نہیں بچتی۔</p>\n<p>مکمل دھندلی تصویر متن یا پریزنٹیشن سلائیڈ کے لیے اچھا پس منظر بنتی ہے۔ تصویر رنگ جوڑتی ہے مگر اوپر والے الفاظ سے توجہ نہیں ہٹاتی۔</p>\n<h2 id=\"setting-brush-size\">برش کا سائز طے کرنا</h2>\n<p>برش کا سائز چھپائی جانے والی تفصیل کے مطابق ہونا چاہیے۔ چہرے کو بڑا برش چاہیے، نمبر پلیٹ کو درمیانہ اور ایک لفظ کو چھوٹا برش چاہیے۔</p>\n<p>بہت بڑا برش ارادے سے زیادہ ڈھانپ دیتا ہے۔ وہ ساتھ والا چہرہ یا تصویر کا مفید حصہ ڈھانپ سکتا ہے جسے چھپانے کی ضرورت نہیں تھی۔</p>\n<p>بہت چھوٹا برش بڑے حصے کو ڈھانپنے میں کئی اسٹرک لیتا ہے، اور اسٹرک کے درمیان خلا حساس تفصیل کی باریک جھلک چھوڑ سکتا ہے۔ کام کرتے ہوئے سائز بدلتے رہیں۔</p>\n<h2 id=\"setting-strength\">بلر شدت اور بلاک سائز طے کرنا</h2>\n<p>بلر شدت اور موزیک بلاک سائز دونوں طے کرتے ہیں کہ کتنی معلومات بچتی ہے۔ اونچی قدریں زیادہ چھپاتی ہیں، کم قدریں کم چھپاتی ہیں۔</p>\n<p>چہرے کے لیے سخت بلر یا بڑے بلاک استعمال کریں۔ ہلکا بلر آنکھیں اور مسکراہٹ دکھاتا رہتا ہے، جو کسی کی حفاظت نہیں کرتا، اور چھوٹے بلاک چہرے کی شکل دکھاتے رہتے ہیں۔</p>\n<p>چھوٹے اسکرین شاٹ کے لیے درمیانہ بلاک سائز کافی ہے۔ متن چھوٹا ہوتا ہے، اس لیے معمولی موزیک بھی حروف کی شکلیں مکمل توڑ دیتا ہے۔ زوم کر کے نتیجہ آزمائیں۔</p>\n<h2 id=\"fixing-mistakes\">رنگتے ہوئے غلطیاں ٹھیک کرنا</h2>\n<p>اگر کوئی اسٹرک غلط ہو جائے تو انڈو بٹن سے اسے ہٹا دیں۔ انڈو ایک ایک اسٹرک پیچھے جاتا ہے، اس لیے اچھا کام ضائع کیے بغیر ایک قدم پیچھے جا سکتے ہیں۔</p>\n<p>اگر پوری سنسرنگ غلط لگے تو ری سیٹ بٹن سے تمام برش اسٹرک صاف کر دیں۔ گندے اسٹرک مرمت کرنے سے دوبارہ شروع کرنا تیز ہوتا ہے۔</p>\n<p>اسٹرک کے درمیان خلا پر نظر رکھیں۔ دو برش اسٹرک کے درمیان متن کی باریک جھلک چھپا ہوا لفظ بتا سکتی ہے، اس لیے اسٹرک تھوڑے اوورلیپ کریں۔ ہر سنسر شدہ حصے کے کنارے بھی جانچیں۔</p>\n<h2 id=\"preview-and-compare\">ڈاؤن لوڈ سے پہلے پیش نظارہ</h2>\n<p>ڈاؤن لوڈ سے پہلے ہمیشہ پیش نظارہ دیکھیں۔ ہر سنسر شدہ حصے کو مکمل سائز میں زوم کر کے یقین کریں کہ کوئی خدوخال، حرف یا نمبر پڑھا نہیں جا سکتا۔</p>\n<p>پس منظر بھی سامنے والے حصے کی طرح جانچیں۔ کھڑکی یا آئینے کی عکاسی وہی چہرہ یا پتہ دکھا سکتی ہے جو آپ نے اصل تصویر میں سنسر کیا تھا۔</p>\n<p>اگر ہو سکے تو تصویر بڑی اسکرین پر دیکھیں۔ فون پر چھپی لگنے والی تفصیل کمپیوٹر مانیٹر پر پڑھی جا سکتی ہے، جہاں تصویر بڑی دکھائی دیتی ہے۔ اگر کچھ پڑھا جا سکے تو شدت بڑھائیں۔</p>\n<h2 id=\"choosing-export-format\">ایکسپورٹ فارمیٹ چننا</h2>\n<p>شیئر کرنے والی تصویروں کے لیے JPG چنیں۔ اس کا فائل سائز چھوٹا رہتا ہے، یہ ہر جگہ چلتا ہے اور سنسر شدہ حصے صاف کمپریس ہوتے ہیں۔</p>\n<p>متن والے اسکرین شاٹ اور گرافکس کے لیے PNG چنیں۔ PNG بغیر نقصان والا ہے، اس لیے بغیر سنسر والے حصوں کے تیز کنارے صاف رہتے ہیں اور شفافیت محفوظ رہتی ہے۔</p>\n<p>چھوٹی فائل اور اچھی کوالٹی چاہیے تو WebP چنیں۔ یہ ویب تصویروں کے لیے بہترین ہے، اگرچہ چند پرانے نظام اب بھی اسے قبول نہیں کرتے۔ یاد رکھیں کہ PNG کے لیے کوالٹی سلائیڈر چھپ جاتا ہے۔</p>\n<h2 id=\"blurring-on-mobile\">فون یا ٹیبلٹ پر بلر کرنا</h2>\n<p>یہ ٹول ٹچ سے کام کرتا ہے، اس لیے آپ اسی فون پر تصویر سنسر کر سکتے ہیں جس سے وہ لی گئی تھی۔ گیلری سے اپ لوڈ کریں اور انگلی سے حساس حصوں پر رنگیں۔</p>\n<p>چھوٹی اسکرین پر بڑا برش استعمال کریں۔ انگلی سے رنگنا ماؤس سے کم درست ہوتا ہے، اس لیے بڑا برش حصہ قابل اعتماد طریقے سے ڈھانپ دیتا ہے۔</p>\n<p>چھوٹی تفصیل رنگنے سے پہلے زوم کریں۔ نمبر پلیٹ یا ایک لفظ کو قریب سے دیکھنا ہوتا ہے، اور زوم فون پر بھی اسٹرک درست بنا دیتا ہے۔ ڈاؤن لوڈ شدہ فائلیں عام ڈاؤن لوڈ فولڈر میں محفوظ ہوتی ہیں۔</p>\n<h2 id=\"blurring-screenshots\">اسکرین شاٹ بلر کرنا</h2>\n<p>Ctrl+V سے اسکرین شاٹ سیدھا پیسٹ کر دیں، محفوظ کرنے کا مرحلہ چھوٹ جاتا ہے۔ تصویر فوراً ٹول میں آ جاتی ہے اور سنسر کے لیے تیار ہوتی ہے۔</p>\n<p>نام، ای میل پتے، پاس ورڈ اور اندرونی یو آر ایل رنگیں۔ ڈیش بورڈ کا اسکرین شاٹ اکثر اس حصے سے زیادہ بتا دیتا ہے جو آپ شیئر کرنا چاہتے تھے۔</p>\n<p>اسکرین شاٹ میں متن کے لیے پکسلیشن استعمال کریں۔ موزیک حروف کی شکلیں مکمل توڑ دیتا ہے، جبکہ نرم بلر مکمل سائز پر الفاظ جزوی طور پر پڑھنے کے قابل چھوڑ سکتا ہے۔ اسکرین شاٹ PNG میں ایکسپورٹ کریں۔</p>\n<h2 id=\"blurring-documents\">دستاویز کی تصویر بلر کرنا</h2>\n<p>دستاویز کی تصویروں میں نام، پتے اور شناختی نمبر کئی جگہ ہوتے ہیں۔ رنگنے سے پہلے ان سب کی فہرست بنائیں، تاکہ کوئی رہ نہ جائے۔</p>\n<p>متن کی پوری لائن ڈھانپیں، صرف حساس لفظ نہیں۔ لائن کی لمبائی اور ارد گرد کے الفاظ چھپا ہوا حصہ بتا سکتے ہیں۔</p>\n<p>دستاویز کی تصویر کے کنارے جانچیں۔ دوسرا صفحہ، عکاسی یا سایہ اسی معلومات کو ایسی جگہ لے سکتا ہے جہاں آپ نے سوچا نہیں تھا۔ اگر دستاویز شیئر کرنی ہی ہو تو حساس حصے کراپ کر کے مکمل ہٹا دینے پر غور کریں۔</p>\n<h2 id=\"troubleshooting\">عام سنسرنگ مسائل کا حل</h2>\n<p>اگر چہرہ اب بھی پہچانا جا سکے تو بلر ہلکا ہے یا بلاک چھوٹے ہیں۔ شدت بڑھائیں اور چہرے پر دوبارہ رنگیں جب تک کوئی خدوخال نظر نہ آئے۔</p>\n<p>اگر متن اب بھی پڑھا جا سکے تو بلر سے پکسلیشن پر جائیں۔ بڑے بلاک والا موزیک حروف کی شکلیں نرم بلر سے کہیں زیادہ قابل اعتماد طریقے سے توڑتا ہے۔</p>\n<p>اگر انڈو اور ری سیٹ بٹن نظر نہ آئیں تو دیکھیں کہ آپ Whole Image موڈ میں تو نہیں ہیں۔ یہ بٹن صرف Brush Area موڈ میں دکھائی دیتے ہیں، جہاں اسٹرک ہوتے ہیں۔</p>\n<h2 id=\"quick-tips\">محفوظ سنسرنگ کے لیے فوری نکات</h2>\n<p>کھلے دل سے سنسر کریں۔ تھوڑا زیادہ ڈھانپنا بے ضرر ہے، جبکہ چہرے یا ہندسے کی باریک جھلک چھوڑنا پورا مقصد ختم کر دیتا ہے۔</p>\n<p>ہر اسٹرک کے بعد زوم کریں۔ فوری زوم جانچ خلا اور رہ جانے والے حصے شیئر شدہ غلطی بننے سے پہلے پکڑ لیتی ہے۔</p>\n<p>صرف سنسر شدہ فائل شیئر کریں۔ اصل کو الگ فولڈر میں رکھیں، اور اسے کبھی اسی پیغام یا پوسٹ کے ساتھ نہ لگائیں۔ ایکسپورٹ کے بعد میٹا ڈیٹا بھی جانچیں۔</p>\n<h2 id=\"blurring-for-presentations\">پریزنٹیشن کے لیے تصویر بلر کرنا</h2>\n<p>دھندلی تصویر صاف سلائیڈ پس منظر بنتی ہے۔ نرم رنگ بصری دلچسپی جوڑتے ہیں، جبکہ اوپر والا متن تیز اور کمرے کے پیچھے سے بھی پڑھنے کے قابل رہتا ہے۔</p>\n<p>Whole Image موڈ میں درمیانہ بلر استعمال کریں، پھر اپنا عنوان اور نکات اوپر رکھیں۔ بلر اتنا سخت ہو کہ متن پڑھا جا سکے، مگر اتنا ہلکا کہ تصویر اب بھی نظر آئے۔</p>\n<p>سلائیڈ کا متن بڑا اور اونچے کنٹراسٹ والا رکھیں۔ گہری دھندلی تصویر پر سفید متن اچھا لگتا ہے، جبکہ گہرا متن ہلکے دھندلے پس منظر پر پڑھا جاتا ہے۔</p>\n<p>پس منظر کو اونچی کوالٹی پر JPG میں ایکسپورٹ کریں۔ صاف پس منظر پوری سلائیڈ کو پیشہ ورانہ دکھاتا ہے، جبکہ کم کوالٹی ایکسپورٹ متن کو بھی نرم کر دیتا ہے۔ موازنے کے لیے <a href=\"/ur/blog/blur-vs-pixelate-tasveer/\">Blur vs Pixelate: Hiding Faces, Text and Details</a> پڑھیں۔ مکمل رہنما کے لیے <a href=\"/ur/blog/tasveer-blur-pixelate-karein-rehnumai/\">Blur and Pixelate Images: Complete Guide</a> دیکھیں، اور مقام کا ڈیٹا مکمل ہٹانے کے لیے <a href=\"/ur/tasveer-metadata-hatayein/\">Remove Image Metadata ٹول</a> استعمال کریں۔</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"گروپ فوٹو میں صرف ایک چہرہ کیسے بلر کروں؟","answer":"Brush Area موڈ استعمال کریں اور بڑے برش سے سخت بلر یا موزیک کے ساتھ صرف اس چہرے پر رنگیں۔ باقی تصویر تیز رہتی ہے۔ بعد میں زوم کر کے یقین کریں کہ پورا سر ڈھکا ہے، بالوں کی لکیر اور کان بھی۔"},{"question":"کیا ایک ہی تصویر کے مختلف حصے بلر اور پکسلیٹ کر سکتا ہوں؟","answer":"جی ہاں۔ چہرے پر Smooth Blur رنگیں، پھر Pixelate Mosaic پر جا کر متن یا نمبر پلیٹ رنگیں۔ اسٹرک کے درمیان موڈ بدل کر ایک تصویر پر دونوں اثر ملا سکتے ہیں۔"},{"question":"نمبر پلیٹ کے لیے کون سا برش سائز بہتر ہے؟","answer":"درمیانہ برش جو پلیٹ کو دو یا تین اسٹرک میں ڈھانپ دے، اچھا رہتا ہے۔ متن کے لیے درمیانے سے بڑے بلاک سائز کے ساتھ پکسلیشن استعمال کریں، کیونکہ موزیک حروف کی شکلیں توڑتا ہے۔ زوم کر کے یقین کریں کہ کوئی ہندسہ پڑھا نہیں جا سکتا۔"},{"question":"فون پر اسکرین شاٹ کیسے بلر کروں؟","answer":"فون کے براؤزر میں ٹول کھولیں، گیلری سے اسکرین شاٹ اپ لوڈ کریں اور Brush Area موڈ چنیں۔ انگلی سے ناموں اور پاس ورڈ پر رنگیں، متن کے لیے بڑا برش اور پکسلیشن استعمال کریں، پھر سنسر شدہ کاپی ڈاؤن لوڈ کر لیں۔"},{"question":"انڈو اور ری سیٹ بٹن کیوں نظر نہیں آ رہے؟","answer":"یہ بٹن صرف Brush Area موڈ میں دکھائی دیتے ہیں، جہاں اسٹرک ہوتے ہیں جنہیں واپس لیا جا سکے۔ Whole Image موڈ میں کوئی برش اسٹرک نہیں ہوتا، اس لیے بٹن چھپ جاتے ہیں۔ رنگنے اور انڈو استعمال کرنے کے لیے Brush Area موڈ پر واپس جائیں۔"},{"question":"کیا اپنے بچے کی دھندلی تصویر آن لائن شیئر کرنا محفوظ ہے؟","answer":"مضبوط بلر یا پکسلیٹ شدہ چہرہ نظر آنے والے چہرے سے کہیں زیادہ محفوظ ہے، مگر کوئی طریقہ مکمل نہیں ہوتا۔ بڑا موزیک یا بھاری بلر استعمال کریں، پورا سر ڈھانپیں اور نتیجہ مکمل سائز میں جانچیں۔ اصل فائل کہیں شیئر نہ کریں۔"}];
